-- SpeakUp English - all ten database migrations in the verified order.
-- Generated from supabase/migrations/ in the order enforced by
-- `npm run test:migrations`. Do not edit this file; edit the migrations.
--
-- How to use:
--   1. Supabase Dashboard -> SQL Editor -> New query.
--   2. Paste this whole file and press Run once.
--   3. Everything runs in ONE transaction. If any statement fails, nothing is
--      applied and the database is left exactly as it was.
--
-- Do not run this on a database that already has these tables. Use a fresh
-- project. The SQL Editor runs as the database owner and bypasses RLS; that is
-- expected for setup and is not evidence that student isolation works.

begin;

-- ============================================================
-- 1/10  20261025150000_create_student_profiles.sql
-- ============================================================

-- Phase 5, migration 1: minimal student profiles.
-- Apply this file once, before the other progress migrations.
--
-- Profiles store only a display name and timestamps. Email addresses, passwords,
-- tokens and roles remain in Supabase Auth and are never duplicated here.

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_display_name_check check (
    display_name = btrim(display_name)
    and char_length(display_name) between 1 and 80
  )
);

comment on table public.profiles is
  'Minimal student profile, one row per Supabase auth user.';
comment on column public.profiles.display_name is
  'Display name only. Do not store email addresses, tokens or role data here.';

-- Derives a safe display name from auth metadata without storing anything else.
create function public.display_name_from_metadata(metadata jsonb, email text)
returns text
language sql
immutable
set search_path = ''
as $$
  select coalesce(
    nullif(btrim(left(btrim(coalesce(metadata ->> 'full_name', '')), 80)), ''),
    nullif(btrim(left(btrim(coalesce(metadata ->> 'name', '')), 80)), ''),
    nullif(
      btrim(left(btrim(split_part(coalesce(email, ''), '@', 1)), 80)),
      ''
    ),
    'Student'
  );
$$;

revoke all on function public.display_name_from_metadata(jsonb, text)
  from public, anon, authenticated;

create function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

revoke all on function public.set_updated_at()
  from public, anon, authenticated;

create trigger profiles_set_updated_at
before update on public.profiles
for each row execute function public.set_updated_at();

-- New auth users receive a profile automatically. This runs as the function
-- owner because auth.users is not writable by student sessions.
create function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (
    new.id,
    public.display_name_from_metadata(new.raw_user_meta_data, new.email)
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

revoke all on function public.handle_new_user()
  from public, anon, authenticated;

create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

-- Backfill profiles for accounts that already exist when this migration runs.
insert into public.profiles (id, display_name)
select
  users.id,
  public.display_name_from_metadata(users.raw_user_meta_data, users.email)
from auth.users as users
on conflict (id) do nothing;


-- ============================================================
-- 2/10  20261025150100_create_learning_progress.sql
-- ============================================================

-- Phase 5, migration 2: lesson progress, quiz attempts and best-score logic.
-- Apply this file once, after the student profiles migration.
--
-- Course and lesson identifiers are the stable slugs already used by the
-- curriculum and URLs. Titles may change without breaking saved progress.

create table public.lesson_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  course_slug text not null,
  lesson_slug text not null,
  is_completed boolean not null default false,
  completed_at timestamptz,
  best_score smallint not null default 0,
  best_score_total smallint not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint lesson_progress_pkey primary key (user_id, course_slug, lesson_slug),
  constraint lesson_progress_course_slug_check check (
    char_length(course_slug) between 1 and 120
    and course_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  ),
  constraint lesson_progress_lesson_slug_check check (
    char_length(lesson_slug) between 1 and 120
    and lesson_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  ),
  constraint lesson_progress_score_check check (
    best_score >= 0
    and best_score_total >= 0
    and best_score <= best_score_total
  ),
  constraint lesson_progress_completion_check check (
    (is_completed and completed_at is not null)
    or (not is_completed and completed_at is null)
  )
);

comment on table public.lesson_progress is
  'One row per student, course and lesson. Completion and best quiz score only.';
comment on column public.lesson_progress.best_score is
  'Best score achieved, updated by the quiz attempt trigger.';

create index lesson_progress_recent_activity_idx
  on public.lesson_progress (user_id, updated_at desc);

create index lesson_progress_completed_course_idx
  on public.lesson_progress (user_id, course_slug)
  where is_completed;

create trigger lesson_progress_set_updated_at
before update on public.lesson_progress
for each row execute function public.set_updated_at();

create table public.quiz_attempts (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  course_slug text not null,
  lesson_slug text not null,
  score smallint not null,
  total_questions smallint not null,
  attempted_at timestamptz not null default now(),
  constraint quiz_attempts_course_slug_check check (
    char_length(course_slug) between 1 and 120
    and course_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  ),
  constraint quiz_attempts_lesson_slug_check check (
    char_length(lesson_slug) between 1 and 120
    and lesson_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  ),
  constraint quiz_attempts_score_check check (
    score >= 0
    and total_questions > 0
    and score <= total_questions
  )
);

comment on table public.quiz_attempts is
  'Minimal quiz analytics: course and lesson slugs, score, total and timestamp. No answers or personal data.';

create index quiz_attempts_recent_activity_idx
  on public.quiz_attempts (user_id, attempted_at desc);

create index quiz_attempts_lesson_idx
  on public.quiz_attempts (user_id, course_slug, lesson_slug, attempted_at desc);

-- Recomputes the lesson high-water mark from the newly inserted attempt. The
-- database, not the browser, is the only writer of best_score.
create function public.record_quiz_attempt_best_score()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.user_id is distinct from auth.uid() then
    raise exception 'Quiz attempts can only update the submitting student''s progress.'
      using errcode = '42501';
  end if;

  insert into public.lesson_progress as progress (
    user_id,
    course_slug,
    lesson_slug,
    is_completed,
    completed_at,
    best_score,
    best_score_total
  )
  values (
    new.user_id,
    new.course_slug,
    new.lesson_slug,
    false,
    null,
    new.score,
    new.total_questions
  )
  on conflict on constraint lesson_progress_pkey do update
  set
    best_score = excluded.best_score,
    best_score_total = excluded.best_score_total
  where
    excluded.best_score_total > 0
    and (
      progress.best_score_total = 0
      or excluded.best_score * progress.best_score_total
         > progress.best_score * excluded.best_score_total
      or (
        excluded.best_score * progress.best_score_total
          = progress.best_score * excluded.best_score_total
        and excluded.best_score > progress.best_score
      )
    );

  return new;
end;
$$;

revoke all on function public.record_quiz_attempt_best_score()
  from public, anon, authenticated;

create trigger quiz_attempts_record_best_score
after insert on public.quiz_attempts
for each row execute function public.record_quiz_attempt_best_score();

-- Idempotent explicit completion. A repeated call leaves completed_at and
-- updated_at unchanged. Quiz attempts never call this function.
create function public.mark_lesson_complete(
  target_course_slug text,
  target_lesson_slug text
)
returns table (
  is_completed boolean,
  completed_at timestamptz,
  best_score smallint,
  best_score_total smallint,
  updated_at timestamptz
)
language plpgsql
security invoker
set search_path = ''
as $$
declare
  student_id uuid := auth.uid();
begin
  if student_id is null then
    raise exception 'You must be signed in to save progress.'
      using errcode = '42501';
  end if;

  if target_course_slug is null
     or target_lesson_slug is null
     or char_length(target_course_slug) not between 1 and 120
     or char_length(target_lesson_slug) not between 1 and 120
     or target_course_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
     or target_lesson_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  then
    raise exception 'Invalid course or lesson identifier.'
      using errcode = '22023';
  end if;

  insert into public.lesson_progress as progress (
    user_id,
    course_slug,
    lesson_slug,
    is_completed,
    completed_at
  )
  values (
    student_id,
    target_course_slug,
    target_lesson_slug,
    true,
    now()
  )
  on conflict on constraint lesson_progress_pkey do update
  set
    is_completed = true,
    completed_at = coalesce(progress.completed_at, now())
  where progress.is_completed = false;

  return query
  select
    progress.is_completed,
    progress.completed_at,
    progress.best_score,
    progress.best_score_total,
    progress.updated_at
  from public.lesson_progress as progress
  where progress.user_id = student_id
    and progress.course_slug = target_course_slug
    and progress.lesson_slug = target_lesson_slug;
end;
$$;


-- ============================================================
-- 3/10  20261025150200_enable_progress_rls.sql
-- ============================================================

-- Phase 5, migration 3: row level security and least-privilege grants.
-- Apply this file once, after the learning progress migration.
--
-- Students can only touch rows whose user_id matches their verified auth.uid().
-- Anonymous visitors receive no table or function privileges. The service-role
-- key is never used by this application.

alter table public.profiles enable row level security;
alter table public.lesson_progress enable row level security;
alter table public.quiz_attempts enable row level security;

-- Profiles ------------------------------------------------------------------

create policy "profiles_select_own"
on public.profiles
for select
to authenticated
using ((select auth.uid()) = id);

create policy "profiles_insert_own"
on public.profiles
for insert
to authenticated
with check ((select auth.uid()) = id);

create policy "profiles_update_own"
on public.profiles
for update
to authenticated
using ((select auth.uid()) = id)
with check ((select auth.uid()) = id);

-- Lesson progress -----------------------------------------------------------

create policy "lesson_progress_select_own"
on public.lesson_progress
for select
to authenticated
using ((select auth.uid()) = user_id);

create policy "lesson_progress_insert_own"
on public.lesson_progress
for insert
to authenticated
with check ((select auth.uid()) = user_id);

create policy "lesson_progress_update_own"
on public.lesson_progress
for update
to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);

create policy "lesson_progress_delete_own"
on public.lesson_progress
for delete
to authenticated
using ((select auth.uid()) = user_id);

-- Quiz attempts -------------------------------------------------------------

create policy "quiz_attempts_select_own"
on public.quiz_attempts
for select
to authenticated
using ((select auth.uid()) = user_id);

create policy "quiz_attempts_insert_own"
on public.quiz_attempts
for insert
to authenticated
with check ((select auth.uid()) = user_id);

create policy "quiz_attempts_delete_own"
on public.quiz_attempts
for delete
to authenticated
using ((select auth.uid()) = user_id);

-- Attempts are intentionally immutable: there is no UPDATE policy or grant.

-- Grants --------------------------------------------------------------------
-- Supabase default privileges can grant broad access to new public tables, so
-- remove everything first and grant only the operations the student UI needs.

revoke all on table public.profiles from public, anon, authenticated;
revoke all on table public.lesson_progress from public, anon, authenticated;
revoke all on table public.quiz_attempts from public, anon, authenticated;

grant select on table public.profiles to authenticated;
grant insert (id, display_name) on table public.profiles to authenticated;
grant update (display_name) on table public.profiles to authenticated;

grant select on table public.lesson_progress to authenticated;
grant insert (
  user_id,
  course_slug,
  lesson_slug,
  is_completed,
  completed_at
) on table public.lesson_progress to authenticated;
grant update (is_completed, completed_at)
  on table public.lesson_progress to authenticated;
grant delete on table public.lesson_progress to authenticated;

grant select on table public.quiz_attempts to authenticated;
grant insert (
  user_id,
  course_slug,
  lesson_slug,
  score,
  total_questions
) on table public.quiz_attempts to authenticated;
grant delete on table public.quiz_attempts to authenticated;

-- The completion function runs with the caller's privileges, so the RLS
-- policies and column grants above still apply inside it.
revoke all on function public.mark_lesson_complete(text, text)
  from public, anon, authenticated;
grant execute on function public.mark_lesson_complete(text, text)
  to authenticated;

-- No profile column can assign roles or permissions. There is deliberately no
-- role, admin, plan or entitlement column in any of these tables.


-- ============================================================
-- 4/10  20261025150300_create_progress_summary_views.sql
-- ============================================================

-- Phase 5, migration 4: per-course progress and quiz aggregates.
-- Apply this file once, after the RLS migration.
--
-- Views use security_invoker so the caller's RLS policies and grants apply.
-- They return only the signed-in student's rows; no aggregate leaks across users.

create view public.student_course_progress
with (security_invoker = true)
as
select
  user_id,
  course_slug,
  count(*) filter (where is_completed)::integer as lessons_completed,
  count(*)::integer as lessons_tracked,
  max(updated_at) as last_activity_at
from public.lesson_progress
group by user_id, course_slug;

comment on view public.student_course_progress is
  'Per-student completion totals for each course, filtered by row level security.';

create view public.student_course_quiz_stats
with (security_invoker = true)
as
select
  user_id,
  course_slug,
  count(*)::integer as attempt_count,
  max(attempted_at) as last_attempt_at,
  (
    array_agg(
      score
      order by
        (score::numeric / total_questions) desc,
        score desc,
        attempted_at asc
    )
  )[1] as best_score,
  (
    array_agg(
      total_questions
      order by
        (score::numeric / total_questions) desc,
        score desc,
        attempted_at asc
    )
  )[1] as best_score_total
from public.quiz_attempts
group by user_id, course_slug;

comment on view public.student_course_quiz_stats is
  'Per-student quiz attempt count and best score for each course, filtered by row level security.';

revoke all on table public.student_course_progress
  from public, anon, authenticated;
revoke all on table public.student_course_quiz_stats
  from public, anon, authenticated;

grant select on table public.student_course_progress to authenticated;
grant select on table public.student_course_quiz_stats to authenticated;


-- ============================================================
-- 5/10  20261026120000_create_admin_roles_and_audit.sql
-- ============================================================

-- Phase 7, migration 1: administrator allow-list and audit trail.
-- Apply this file once, after all Phase 5 migrations.
--
-- Administrator status is stored only in public.admin_users, which has no
-- grants and no RLS policies. A signed-in user cannot read it, insert into it,
-- update it or promote themselves through the API. The first administrator is
-- added deliberately with SQL in the Supabase SQL editor; see
-- docs/admin-database-setup.md. Editable auth metadata is never consulted.

create table public.admin_users (
  user_id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  note text not null default '',
  created_at timestamptz not null default now(),
  constraint admin_users_email_check check (
    char_length(email) between 3 and 320
    and email like '%@%'
  ),
  constraint admin_users_note_check check (char_length(note) <= 500)
);

comment on table public.admin_users is
  'Trusted administrator allow-list. Managed manually in the Supabase SQL editor, never through application code.';

alter table public.admin_users enable row level security;

-- No policies are created on purpose. Even an administrator cannot browse this
-- table through PostgREST; the application asks public.is_admin() instead.
revoke all on table public.admin_users from public, anon, authenticated;

create function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.admin_users
    where user_id = auth.uid()
  );
$$;

comment on function public.is_admin() is
  'Returns true only when the current auth.uid() has an explicit row in public.admin_users.';

revoke all on function public.is_admin() from public, anon, authenticated;
grant execute on function public.is_admin() to authenticated;

-- Audit trail -----------------------------------------------------------------

create table public.admin_audit_log (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references auth.users (id) on delete set null,
  actor_email text,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  summary text not null,
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint admin_audit_log_action_check check (
    char_length(action) between 2 and 60
    and action ~ '^[a-z][a-z0-9_]*$'
  ),
  constraint admin_audit_log_entity_type_check check (
    entity_type in ('course', 'unit', 'lesson', 'system')
  ),
  constraint admin_audit_log_summary_check check (
    char_length(summary) between 1 and 300
  ),
  constraint admin_audit_log_detail_check check (
    jsonb_typeof(detail) = 'object'
  )
);

comment on table public.admin_audit_log is
  'Recent administrative changes. Written by security-definer triggers and publishing functions; administrators can read but not alter it.';

create index admin_audit_log_created_at_idx
  on public.admin_audit_log (created_at desc);

alter table public.admin_audit_log enable row level security;

create policy "admin_audit_log_select_admins"
on public.admin_audit_log
for select
to authenticated
using (public.is_admin());

revoke all on table public.admin_audit_log from public, anon, authenticated;
grant select on table public.admin_audit_log to authenticated;

-- No insert, update or delete grants: audit rows are append-only and can only
-- be written by security-definer functions owned by the database owner.


-- ============================================================
-- 6/10  20261026120100_create_content_tables.sql
-- ============================================================

-- Phase 7, migration 2: draft content, published snapshots and quiz answer keys.
-- Apply this file once, after the admin roles migration.
--
-- Draft tables are private to administrators. Published tables are readable by
-- everyone but can only be written by the security-definer publishing functions
-- in the next migration. Correct answers live in a separate table that has no
-- grants and no RLS policies, so they are never exposed with published lessons.

-- Draft content ---------------------------------------------------------------

create table public.content_courses (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  summary text not null,
  description text not null default '',
  level text not null,
  skill text not null,
  outcomes text[] not null default '{}',
  metadata jsonb not null default '{}'::jsonb,
  premium boolean not null default false,
  hours integer not null default 1,
  status text not null default 'draft',
  sort_order integer not null default 0,
  last_published_at timestamptz,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint content_courses_slug_check check (
    char_length(slug) between 1 and 120
    and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  ),
  constraint content_courses_title_check check (
    char_length(title) between 1 and 160
  ),
  constraint content_courses_summary_check check (
    char_length(summary) between 1 and 500
  ),
  constraint content_courses_description_check check (
    char_length(description) <= 4000
  ),
  constraint content_courses_level_check check (
    level in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')
  ),
  constraint content_courses_skill_check check (
    skill in (
      'grammar',
      'listening',
      'speaking',
      'pronunciation',
      'vocabulary',
      'reading',
      'writing'
    )
  ),
  constraint content_courses_outcomes_check check (
    cardinality(outcomes) <= 12
    and array_position(outcomes, null) is null
  ),
  constraint content_courses_metadata_check check (
    jsonb_typeof(metadata) = 'object'
    and pg_column_size(metadata) <= 20000
  ),
  constraint content_courses_hours_check check (hours between 1 and 200),
  constraint content_courses_status_check check (
    status in ('draft', 'published', 'archived')
  )
);

comment on table public.content_courses is
  'Administrator-managed course drafts. Only published snapshots are visible to students.';

create index content_courses_status_level_skill_idx
  on public.content_courses (status, level, skill);

create table public.content_units (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.content_courses (id) on delete cascade,
  title text not null,
  description text not null default '',
  status text not null default 'draft',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint content_units_title_check check (
    char_length(title) between 1 and 200
  ),
  constraint content_units_description_check check (
    char_length(description) <= 2000
  ),
  constraint content_units_status_check check (
    status in ('draft', 'published')
  ),
  constraint content_units_id_course_key unique (id, course_id)
);

comment on table public.content_units is
  'Ordered course units in the administrator draft workspace.';

create index content_units_course_order_idx
  on public.content_units (course_id, sort_order, created_at);

create table public.content_lessons (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.content_courses (id) on delete cascade,
  unit_id uuid not null,
  slug text not null,
  title text not null,
  summary text not null,
  objective text not null,
  minutes integer not null default 10,
  blocks jsonb not null default '[]'::jsonb,
  quiz jsonb not null default '[]'::jsonb,
  status text not null default 'draft',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint content_lessons_unit_course_fk
    foreign key (unit_id, course_id)
    references public.content_units (id, course_id)
    on delete cascade,
  constraint content_lessons_slug_check check (
    char_length(slug) between 1 and 120
    and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  ),
  constraint content_lessons_title_check check (
    char_length(title) between 1 and 200
  ),
  constraint content_lessons_summary_check check (
    char_length(summary) between 1 and 1000
  ),
  constraint content_lessons_objective_check check (
    char_length(objective) between 1 and 1000
  ),
  constraint content_lessons_minutes_check check (minutes between 1 and 600),
  constraint content_lessons_blocks_check check (jsonb_typeof(blocks) = 'array'),
  constraint content_lessons_quiz_check check (jsonb_typeof(quiz) = 'array'),
  constraint content_lessons_status_check check (
    status in ('draft', 'published')
  ),
  constraint content_lessons_course_slug_key unique (course_id, slug)
);

comment on table public.content_lessons is
  'Lesson drafts including full quiz answer keys. Never granted to anonymous visitors or ordinary students.';

create index content_lessons_unit_order_idx
  on public.content_lessons (unit_id, sort_order, created_at);

create index content_lessons_course_status_idx
  on public.content_lessons (course_id, status);

-- Published snapshots ---------------------------------------------------------

create table public.published_courses (
  course_id uuid primary key
    references public.content_courses (id) on delete cascade,
  slug text not null unique,
  title text not null,
  summary text not null,
  description text not null,
  level text not null,
  skill text not null,
  outcomes text[] not null default '{}',
  metadata jsonb not null default '{}'::jsonb,
  premium boolean not null default false,
  hours integer not null,
  lesson_count integer not null,
  published_at timestamptz not null default now(),
  constraint published_courses_slug_check check (
    char_length(slug) between 1 and 120
    and slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
  ),
  constraint published_courses_level_check check (
    level in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')
  ),
  constraint published_courses_skill_check check (
    skill in (
      'grammar',
      'listening',
      'speaking',
      'pronunciation',
      'vocabulary',
      'reading',
      'writing'
    )
  ),
  constraint published_courses_lesson_count_check check (lesson_count >= 1),
  constraint published_courses_hours_check check (hours between 1 and 200)
);

comment on table public.published_courses is
  'Immutable snapshots of published course metadata. Replaced only by publish_content_course().';

create table public.published_units (
  id uuid primary key,
  course_id uuid not null
    references public.published_courses (course_id) on delete cascade,
  title text not null,
  description text not null default '',
  sort_order integer not null default 0,
  constraint published_units_id_course_key unique (id, course_id)
);

create index published_units_course_order_idx
  on public.published_units (course_id, sort_order);

create table public.published_lessons (
  id uuid primary key,
  course_id uuid not null,
  unit_id uuid not null,
  slug text not null,
  title text not null,
  summary text not null,
  objective text not null,
  minutes integer not null,
  blocks jsonb not null,
  questions jsonb not null,
  sort_order integer not null default 0,
  constraint published_lessons_unit_course_fk
    foreign key (unit_id, course_id)
    references public.published_units (id, course_id)
    on delete cascade,
  constraint published_lessons_course_slug_key unique (course_id, slug),
  constraint published_lessons_questions_check check (
    jsonb_typeof(questions) = 'array'
  ),
  constraint published_lessons_blocks_check check (
    jsonb_typeof(blocks) = 'array'
  )
);

comment on table public.published_lessons is
  'Published lesson bodies with sanitized questions: id, question and options only. Correct answers are not stored here.';

create index published_lessons_unit_order_idx
  on public.published_lessons (unit_id, sort_order);

create table public.published_quiz_answers (
  lesson_id uuid primary key
    references public.published_lessons (id) on delete cascade,
  course_slug text not null,
  lesson_slug text not null,
  answers jsonb not null,
  constraint published_quiz_answers_answers_check check (
    jsonb_typeof(answers) = 'array'
  )
);

comment on table public.published_quiz_answers is
  'Private answer keys for published quizzes. Only grade_published_lesson_quiz() can read them.';

create index published_quiz_answers_identity_idx
  on public.published_quiz_answers (course_slug, lesson_slug);

-- Row level security and least-privilege grants --------------------------------

alter table public.content_courses enable row level security;
alter table public.content_units enable row level security;
alter table public.content_lessons enable row level security;
alter table public.published_courses enable row level security;
alter table public.published_units enable row level security;
alter table public.published_lessons enable row level security;
alter table public.published_quiz_answers enable row level security;

